"""Generate Colab/Kaggle notebooks for `full`-profile runs (execution mode C). Generated, not executed here."""

from __future__ import annotations

import json
from pathlib import Path

REPO = "https://github.com/bhavishya200604-hub/-AeroSynapse-Einstein"


def make_notebook(phase: int, profile: str = "full") -> dict[str, object]:
    cells = [
        (
            "markdown",
            f"# AeroSynapse-Einstein — Phase {phase} ({profile} profile)\n\nRESEARCH USE ONLY. This notebook "
            "was generated by `aerosynapse.experiments.notebooks` and was **not executed** by the authors; "
            "results appear only after you run it.",
        ),
        ("code", f"!git clone {REPO} aerosynapse && cd aerosynapse && pip install -q -e .[torch]"),
        ("code", "import os; os.chdir('aerosynapse'); !aerosynapse doctor"),
        ("code", f"!python scripts/run_phase{phase}.py --profile {profile}"),
        (
            "code",
            "import json; print(json.dumps(json.load(open('results/' + sorted(os.listdir('results'))[0] + "
            "'/metrics.json')), indent=1)[:3000])",
        ),
    ]
    return {
        "nbformat": 4,
        "nbformat_minor": 5,
        "metadata": {"kernelspec": {"name": "python3", "display_name": "Python 3"}},
        "cells": [
            {
                "cell_type": t,
                "metadata": {},
                "source": s,
                **({"outputs": [], "execution_count": None} if t == "code" else {}),
            }
            for t, s in cells
        ],
    }


def write_notebooks(out_dir: str | Path, phases: tuple[int, ...] = (2, 3, 4, 5, 6)) -> list[Path]:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    paths = []
    for ph in phases:
        p = out / f"phase{ph}_full_colab.ipynb"
        p.write_text(json.dumps(make_notebook(ph), indent=1), encoding="utf-8")
        paths.append(p)
    return paths
